import{_ as o,o as r,c as a,a2 as e}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"请求首字慢怎么排查","description":"ChatGPT 发消息后第一个字出现得很慢？先新建会话测试，区分是网络问题还是会话上下文问题；压缩旧会话、限制图片数量可以明显提速。","frontmatter":{"title":"请求首字慢怎么排查","description":"ChatGPT 发消息后第一个字出现得很慢？先新建会话测试，区分是网络问题还是会话上下文问题；压缩旧会话、限制图片数量可以明显提速。"},"headers":[],"relativePath":"troubleshooting/slow-response.md","filePath":"troubleshooting/slow-response.md","lastUpdated":null}'),s={name:"troubleshooting/slow-response.md"};function n(l,t,d,i,h,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="请求首字慢怎么排查" tabindex="-1">请求首字慢怎么排查 <a class="header-anchor" href="#请求首字慢怎么排查" aria-label="Permalink to &quot;请求首字慢怎么排查&quot;">​</a></h1><p><strong>现象</strong>：在 ChatGPT 里发一条消息，第一个字要等 <strong>30～120 秒</strong>才出现，而且<strong>连续出现</strong>——不是偶尔一次，是每次发消息都这么慢。</p><p>先别急着怀疑网络，按下面的顺序查，多数情况自己就能解决。</p><h2 id="新建一个会话试试" tabindex="-1">新建一个会话试试 <a class="header-anchor" href="#新建一个会话试试" aria-label="Permalink to &quot;新建一个会话试试&quot;">​</a></h2><p>点「新建会话」（或新开一个 Codex 会话），发同样的消息：</p><ul><li><strong>新会话回复很快</strong> → 问题不在网络，而在<strong>原来的会话本身</strong>，继续往下看。</li><li><strong>新会话也一样慢</strong> → 大概率是网络或服务端的问题，去看 <a href="/troubleshooting/network">网络与连接排查</a>。</li></ul><h2 id="清理会话里的图片" tabindex="-1">清理会话里的图片 <a class="header-anchor" href="#清理会话里的图片" aria-label="Permalink to &quot;清理会话里的图片&quot;">​</a></h2><p>如果新会话快、旧会话慢，原因通常是<strong>旧会话的上下文太大</strong>，其中最常见的是<strong>图片太多</strong>。</p><p>每次发消息，ChatGPT 都要把整个会话的内容（包括里面的所有图片）重新传输一遍。图片多了，传输耗时就会明显增加——会话越长、图片越多，第一个字就来得越慢。</p><p>解决办法：</p><ul><li><strong>压缩之前的会话</strong>：把旧会话压缩成摘要，让上下文变小，再继续使用。</li><li><strong>限制会话图片的上限</strong>：控制一个会话里放多少张图片，图片太多了就先清理，或者开一个新会话。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>测试</th><th>结果</th><th>怎么处理</th></tr></thead><tbody><tr><td>新建会话</td><td>变快了</td><td>旧会话上下文太大：压缩会话、减少图片</td></tr><tr><td>新建会话</td><td>还是一样慢</td><td>网络或服务端问题：<a href="/troubleshooting/network">网络与连接排查</a></td></tr></tbody></table>',13)])])}const c=o(s,[["render",n]]);export{u as __pageData,c as default};
